ll power(ll x, ll p) {
  if (p == 0)
    return 1;

  ll ans = 1;
  if (p % 2 == 1)
    ans = (ans * x) % MOD;

  ll c = power(x, p / 2);

  ans = ((ans * c) % MOD * c) % MOD;

  return ans;
}

